1452	+	if err != nil {
1453	+		return nil, fmt.Errorf("okf check: stat bundle path %q: %w", cleanBundlePath, err)
1454	+	}
1455	+	if !info.IsDir() {
1456	+		return nil, fmt.Errorf("okf check: bundle path must be a directory: %s", cleanBundlePath)
1457	+	}
1458	+
1459	+	typeSet := normalizeTypeSet(options.Types)
1460	+	issues := make([]models.LintIssue, 0)
1461	+	err = filepath.WalkDir(cleanBundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
1462	+		if walkErr != nil {
1463	+			return walkErr
1464	+		}
1465	+		if err := ctx.Err(); err != nil {
1466	+			return err
1467	+		}
1468	+		if currentPath == cleanBundlePath {
1469	+			return nil
1470	+		}
1471	+		if entry.Type()&fs.ModeSymlink != 0 {
