1617	+		return "", "", "", "", fmt.Errorf("source document path is required")
1618	+	}
1619	+	if filepath.IsAbs(source) {
1620	+		candidates = append(candidates, source)
1621	+	} else {
1622	+		candidates = append(candidates, source)
1623	+		if strings.TrimSpace(input.VaultPath) != "" {
1624	+			candidates = append(candidates, filepath.Join(input.VaultPath, filepath.FromSlash(source)))
1625	+		}
1626	+	}
1627	+	for _, candidate := range candidates {
1628	+		info, statErr := os.Stat(candidate)
1629	+		if statErr != nil {
1630	+			continue
1631	+		}
1632	+		if info.IsDir() {
1633	+			return "", "", "", "", fmt.Errorf("source document %q must be a file", candidate)
1634	+		}
1635	+		absolutePath, err := filepath.Abs(candidate)
1636	+		if err != nil {
1637	+			return "", "", "", "", fmt.Errorf("resolve source path %q: %w", candidate, err)
1638	+		}
1639	+		topicRoot, topicSlug = discoverTopicRoot(input.VaultPath, absolutePath)
1640	+		if topicRoot != "" {
1641	+			relative, relErr := filepath.Rel(topicRoot, absolutePath)
1642	+			if relErr != nil {
1643	+				return "", "", "", "", fmt.Errorf("derive source topic path: %w", relErr)
1644	+			}
1645	+			return absolutePath, topicRoot, topicSlug, vault.ToPosixPath(relative), nil
1646	+		}
1647	+		return absolutePath, "", "", vault.ToPosixPath(filepath.Base(absolutePath)), nil
1648	+	}
1649	+	return "", "", "", "", fmt.Errorf("source document not found: %s", source)
1650	+}
