1652	+func discoverTopicRoot(vaultPath, sourcePath string) (string, string) {
1653	+	cleanVault := strings.TrimSpace(vaultPath)
1654	+	current := filepath.Dir(sourcePath)
1655	+	for {
1656	+		if cleanVault != "" && !vault.IsPathInside(cleanVault, current) {
1657	+			return "", ""
1658	+		}
1659	+		if isRegularFile(filepath.Join(current, "CLAUDE.md")) {
1660	+			if cleanVault == "" {
1661	+				return current, filepath.Base(current)
1662	+			}
1663	+			relative, err := filepath.Rel(cleanVault, current)
1664	+			if err != nil {
1665	+				return current, filepath.Base(current)
1666	+			}
1667	+			return current, vault.ToPosixPath(relative)
1668	+		}
1669	+		parent := filepath.Dir(current)
1670	+		if parent == current {
1671	+			break
1672	+		}
1673	+		current = parent
1674	+	}
1675	+	return "", ""
