1781	+func mappedTargetPath(target, sourceTopicSlug string) string {
1782	+	target = vault.ToPosixPath(strings.TrimSpace(target))
1783	+	fragment := ""
1784	+	if before, after, found := strings.Cut(target, "#"); found {
1785	+		target = before
1786	+		fragment = "#" + after
1787	+	}
1788	+	target = strings.TrimPrefix(target, "/")
1789	+	if sourceTopicSlug != "" {
1790	+		prefix := strings.Trim(sourceTopicSlug, "/") + "/"
1791	+		target = strings.TrimPrefix(target, prefix)
1792	+	}
1793	+	return conceptKey(target) + ".md" + fragment
