1808	+func dedupeStrings(values []string) []string {
1809	+	if len(values) == 0 {
1810	+		return nil
1811	+	}
1812	+	deduped := values[:0]
1813	+	var previous string
1814	+	for index, value := range values {
1815	+		if index > 0 && value == previous {
1816	+			continue
1817	+		}
1818	+		deduped = append(deduped, value)
1819	+		previous = value
1820	+	}
1821	+	return append([]string(nil), deduped...)
1822	+}
