1824	+func loadConcepts(bundlePath string) ([]conceptInfo, string, error) {
1825	+	okfVersion := OKFVersion
1826	+	indexPath := filepath.Join(bundlePath, "index.md")
1827	+	if content, err := os.ReadFile(indexPath); err == nil {
1828	+		values, _, parseErr := frontmatter.Parse(string(content))
1829	+		if parseErr != nil {
1830	+			return nil, "", fmt.Errorf("parse index.md: %w", parseErr)
1831	+		}
1832	+		if version := strings.TrimSpace(frontmatter.GetString(values, "okf_version")); version != "" {
1833	+			okfVersion = version
1834	+		}
1835	+	} else if !errors.Is(err, os.ErrNotExist) {
1836	+		return nil, "", fmt.Errorf("read index.md: %w", err)
1837	+	}
1838	+
1839	+	concepts := make([]conceptInfo, 0)
1840	+	err := filepath.WalkDir(bundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
1841	+		if walkErr != nil {
1842	+			return walkErr
1843	+		}
1844	+		if currentPath == bundlePath {
1845	+			return nil
1846	+		}
1847	+		if entry.Type()&fs.ModeSymlink != 0 {
1848	+			return nil
1849	+		}
1850	+		if entry.IsDir() {
1851	+			if strings.HasPrefix(entry.Name(), ".") {
1852	+				return filepath.SkipDir
1853	+			}
1854	+			return nil
1855	+		}
1856	+		if !strings.EqualFold(filepath.Ext(entry.Name()), ".md") || isExcludedMarkdown(entry.Name()) {
1857	+			return nil
1858	+		}
1859	+		relativePath, err := filepath.Rel(bundlePath, currentPath)
1860	+		if err != nil {
1861	+			return err
1862	+		}
1863	+		relativePath = vault.ToPosixPath(relativePath)
1864	+		if isIndexFile(relativePath) || isLogFile(relativePath) {
1865	+			return nil
1866	+		}
1867	+		content, err := os.ReadFile(currentPath)
1868	+		if err != nil {
1869	+			return err
1870	+		}
1871	+		values, _, err := frontmatter.Parse(string(content))
1872	+		if err != nil || len(values) == 0 {
1873	+			return nil
1874	+		}
1875	+		conceptType := strings.TrimSpace(frontmatter.GetString(values, "type"))
1876	+		title := strings.TrimSpace(frontmatter.GetString(values, "title"))
1877	+		if title == "" {
1878	+			title = vault.HumanizeSlug(conceptKey(relativePath))
1879	+		}
1880	+		concepts = append(concepts, conceptInfo{
1881	+			RelativePath: relativePath,
1882	+			Type:         firstNonEmpty(conceptType, "Concept"),
1883	+			Title:        title,
1884	+			Description:  strings.TrimSpace(frontmatter.GetString(values, "description")),
1885	+		})
1886	+		return nil
1887	+	})
1888	+	if err != nil {
1889	+		return nil, "", fmt.Errorf("scan concepts: %w", err)
1890	+	}
1891	+	return concepts, okfVersion, nil
1892	+}
