2019	+func insertLogEntry(content, dateHeading, entry string) string {
2020	+	lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
2021	+	if len(lines) == 0 || strings.TrimSpace(lines[0]) == "" {
2022	+		lines = []string{"# Directory Update Log"}
2023	+	}
2024	+	heading := "## " + dateHeading
2025	+	for index, line := range lines {
2026	+		if strings.TrimSpace(line) != heading {
2027	+			continue
2028	+		}
2029	+		next := append([]string{}, lines[:index+1]...)
2030	+		next = append(next, entry)
2031	+		next = append(next, lines[index+1:]...)
2032	+		return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
2033	+	}
2034	+	next := []string{strings.TrimRight(strings.Join(lines[:1], "\n"), "\n"), "", heading, "", entry}
2035	+	if len(lines) > 1 {
2036	+		rest := strings.TrimSpace(strings.Join(lines[1:], "\n"))
2037	+		if rest != "" {
2038	+			next = append(next, "", rest)
2039	+		}
2040	+	}
2041	+	return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
2042	+}
