148	// Check validates an OKF bundle and returns diagnostics.
149	func Check(ctx context.Context, bundlePath string, options CheckOptions) ([]models.LintIssue, error) {
150		if ctx == nil {
151			ctx = context.Background()
152		}
153		cleanBundlePath := strings.TrimSpace(bundlePath)
154		if cleanBundlePath == "" {
155			return nil, fmt.Errorf("okf check: bundle path is required")
156		}
157		info, err := os.Stat(cleanBundlePath)
158		if err != nil {
159			return nil, fmt.Errorf("okf check: stat bundle path %q: %w", cleanBundlePath, err)
160		}
161		if !info.IsDir() {
162			return nil, fmt.Errorf("okf check: bundle path must be a directory: %s", cleanBundlePath)
163		}
164	
165		typeSet := normalizeTypeSet(options.Types)
166		issues := make([]models.LintIssue, 0)
167		err = filepath.WalkDir(cleanBundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
168			if walkErr != nil {
169				return walkErr
170			}
171			if err := ctx.Err(); err != nil {
172				return err
173			}
174			if currentPath == cleanBundlePath {
175				return nil
176			}
177			if entry.Type()&fs.ModeSymlink != 0 {
178				return nil
179			}
180			if entry.IsDir() {
181				if strings.HasPrefix(entry.Name(), ".") {
182					return filepath.SkipDir
183				}
184				return nil
185			}
186			if !strings.EqualFold(filepath.Ext(entry.Name()), ".md") {
187				return nil
188			}
189	
190			relativePath, err := filepath.Rel(cleanBundlePath, currentPath)
191			if err != nil {
192				return fmt.Errorf("derive relative path for %q: %w", currentPath, err)
193			}
194			relativePath = vault.ToPosixPath(relativePath)
195			switch {
196			case isIndexFile(relativePath):
197				issues = append(issues, checkIndexFile(cleanBundlePath, currentPath, relativePath, options.Strict)...)
198			case isLogFile(relativePath):
199				issues = append(issues, checkLogFile(currentPath, relativePath, options.Strict)...)
200			case isExcludedMarkdown(entry.Name()):
201				return nil
202			default:
203				issues = append(issues, checkConceptFile(currentPath, relativePath, typeSet, options.Strict)...)
204			}
205			return nil
206		})
207		if err != nil {
208			return nil, fmt.Errorf("okf check: %w", err)
209		}
210	
211		sortIssues(issues)
212		return issues, nil
213	}
