245	// RegenerateIndex rewrites the root OKF index from concept frontmatter.
246	func RegenerateIndex(bundlePath string) error {
247		concepts, okfVersion, err := loadConcepts(bundlePath)
248		if err != nil {
249			return err
250		}
251		sort.Slice(concepts, func(i, j int) bool {
252			if concepts[i].Type != concepts[j].Type {
253				return concepts[i].Type < concepts[j].Type
254			}
255			if concepts[i].Title != concepts[j].Title {
256				return concepts[i].Title < concepts[j].Title
257			}
258			return concepts[i].RelativePath < concepts[j].RelativePath
259		})
260	
261		var body strings.Builder
262		body.WriteString("# OKF Bundle Index\n")
263		currentType := ""
264		for _, concept := range concepts {
265			if concept.Type != currentType {
266				currentType = concept.Type
267				body.WriteString("\n## ")
268				body.WriteString(currentType)
269				body.WriteString("\n\n")
270			}
271			body.WriteString("* ")
272			body.WriteString(vault.OKFLinkFormatter{}.Link("", concept.RelativePath, concept.Title))
273			if concept.Description != "" {
274				body.WriteString(" - ")
275				body.WriteString(concept.Description)
276			}
277			body.WriteString("\n")
278		}
279	
280		values := map[string]any{"okf_version": firstNonEmpty(okfVersion, OKFVersion)}
281		content, err := frontmatter.Generate(values, body.String())
282		if err != nil {
283			return fmt.Errorf("generate index frontmatter: %w", err)
284		}
285		if err := os.WriteFile(filepath.Join(bundlePath, "index.md"), []byte(content), 0o644); err != nil {
286			return fmt.Errorf("write index.md: %w", err)
287		}
288		return nil
289	}
