291	// InsertLogEntry inserts a newest-first OKF log entry at the bundle root.
292	func InsertLogEntry(bundlePath string, when time.Time, title, conceptPath, sourcePath string) error {
293		logPath := filepath.Join(bundlePath, "log.md")
294		content, err := os.ReadFile(logPath)
295		if errors.Is(err, os.ErrNotExist) {
296			content = []byte("# Directory Update Log\n")
297		} else if err != nil {
298			return fmt.Errorf("read log.md: %w", err)
299		}
300		entry := fmt.Sprintf(
301			"* **Creation**: Promoted %s from `%s`.",
302			vault.OKFLinkFormatter{}.Link("", conceptPath, strings.TrimSpace(title)),
303			sourcePath,
304		)
305		next := insertLogEntry(string(content), when.UTC().Format(frontmatter.DateLayout), entry)
306		if err := os.WriteFile(logPath, []byte(next), 0o644); err != nil {
307			return fmt.Errorf("write log.md: %w", err)
308		}
309		return nil
310	}
