319	func resolveSourceDocument(input PromoteInput) (absolutePath, topicRoot, topicSlug, topicRelativePath string, err error) {
320		candidates := make([]string, 0, 3)
321		source := strings.TrimSpace(input.SourceDocPath)
322		if source == "" {
323			return "", "", "", "", fmt.Errorf("source document path is required")
324		}
325		if filepath.IsAbs(source) {
326			candidates = append(candidates, source)
327		} else {
328			candidates = append(candidates, source)
329			if strings.TrimSpace(input.VaultPath) != "" {
330				candidates = append(candidates, filepath.Join(input.VaultPath, filepath.FromSlash(source)))
331			}
332		}
333		for _, candidate := range candidates {
334			info, statErr := os.Stat(candidate)
335			if statErr != nil {
336				continue
337			}
338			if info.IsDir() {
339				return "", "", "", "", fmt.Errorf("source document %q must be a file", candidate)
340			}
341			absolutePath, err := filepath.Abs(candidate)
342			if err != nil {
343				return "", "", "", "", fmt.Errorf("resolve source path %q: %w", candidate, err)
344			}
345			topicRoot, topicSlug = discoverTopicRoot(input.VaultPath, absolutePath)
346			if topicRoot != "" {
347				relative, relErr := filepath.Rel(topicRoot, absolutePath)
348				if relErr != nil {
349					return "", "", "", "", fmt.Errorf("derive source topic path: %w", relErr)
350				}
351				return absolutePath, topicRoot, topicSlug, vault.ToPosixPath(relative), nil
352			}
353			return absolutePath, "", "", vault.ToPosixPath(filepath.Base(absolutePath)), nil
354		}
355		return "", "", "", "", fmt.Errorf("source document not found: %s", source)
356	}
