358	func discoverTopicRoot(vaultPath, sourcePath string) (string, string) {
359		cleanVault := strings.TrimSpace(vaultPath)
360		current := filepath.Dir(sourcePath)
361		for {
362			if cleanVault != "" && !vault.IsPathInside(cleanVault, current) {
363				return "", ""
364			}
365			if isRegularFile(filepath.Join(current, "CLAUDE.md")) {
366				if cleanVault == "" {
367					return current, filepath.Base(current)
368				}
369				relative, err := filepath.Rel(cleanVault, current)
370				if err != nil {
371					return current, filepath.Base(current)
372				}
373				return current, vault.ToPosixPath(relative)
374			}
375			parent := filepath.Dir(current)
376			if parent == current {
377				break
378			}
379			current = parent
380		}
381		return "", ""
382	}
