389	func allocateConceptPath(bundleRoot, key string) (string, string, error) {
390		for suffix := 1; ; suffix++ {
391			name := key
392			if suffix > 1 {
393				name = fmt.Sprintf("%s-%d", key, suffix)
394			}
395			relativePath := name + ".md"
396			absolutePath := filepath.Join(bundleRoot, filepath.FromSlash(relativePath))
397			if _, err := os.Stat(absolutePath); errors.Is(err, os.ErrNotExist) {
398				return relativePath, absolutePath, nil
399			} else if err != nil {
400				return "", "", err
401			}
402		}
403	}
