410	func typeWarnings(conceptType string, types []string) []string {
411		typeSet := normalizeTypeSet(types)
412		if len(typeSet) == 0 {
413			return nil
414		}
415		if _, ok := typeSet[conceptType]; ok {
416			return nil
417		}
418		return []string{fmt.Sprintf("type %q is outside the configured OKF vocabulary", conceptType)}
419	}
