421	func normalizeTypeSet(types []string) map[string]struct{} {
422		typeSet := make(map[string]struct{})
423		for _, value := range types {
424			value = strings.TrimSpace(value)
425			if value == "" {
426				continue
427			}
428			typeSet[value] = struct{}{}
429		}
430		return typeSet
431	}
