433	func resolveDescription(flagValue, body string) (string, []string) {
434		if description := strings.TrimSpace(flagValue); description != "" {
435			return description, nil
436		}
437		if sentence := firstBodySentence(body); sentence != "" {
438			return sentence, nil
439		}
440		return "", []string{"description is empty because the source body has no sentence fallback"}
441	}
442	
443	func firstBodySentence(body string) string {
444		normalized := markdownSyntaxRunes.Replace(markdownLinkPattern.ReplaceAllString(body, " "))
445		normalized = nonSentenceSpace.ReplaceAllString(strings.TrimSpace(normalized), " ")
446		for index := 0; index < len(normalized); index++ {
447			switch normalized[index] {
448			case '.', '!', '?':
449				if index == len(normalized)-1 || normalized[index+1] == ' ' {
450					return strings.TrimSpace(normalized[:index+1])
451				}
452			}
453		}
454		return ""
455	}
456	
457	func transformWikiLinks(body, sourceTopicSlug, bundleRoot, fromDir, currentPath string) (string, int, []string) {
458		count := 0
459		unresolved := make([]string, 0)
460		formatter := vault.OKFLinkFormatter{}
461		transformed := wikilinkPattern.ReplaceAllStringFunc(body, func(match string) string {
462			inner := strings.TrimSuffix(strings.TrimPrefix(match, "[["), "]]")
463			target, label := splitWikiLink(inner)
464			targetPath := mappedTargetPath(target, sourceTopicSlug)
465			if strings.TrimSpace(label) == "" {
466				label = fallbackWikiLabel(target)
467			}
468			count++
469			if stripFragment(targetPath) != stripFragment(currentPath) && !isRegularFile(filepath.Join(bundleRoot, filepath.FromSlash(stripFragment(targetPath)))) {
470				unresolved = append(unresolved, targetPath)
471			}
472			return formatter.Link(fromDir, targetPath, label)
473		})
474		sort.Strings(unresolved)
475		return transformed, count, dedupeStrings(unresolved)
476	}
477	
478	func splitWikiLink(inner string) (string, string) {
479		parts := strings.SplitN(inner, "|", 2)
480		target := strings.TrimSpace(parts[0])
481		if len(parts) == 1 {
482			return target, ""
483		}
484		return target, strings.TrimSpace(parts[1])
485	}
486	
487	func mappedTargetPath(target, sourceTopicSlug string) string {
488		target = vault.ToPosixPath(strings.TrimSpace(target))
489		fragment := ""
490		if before, after, found := strings.Cut(target, "#"); found {
491			target = before
492			fragment = "#" + after
493		}
494		target = strings.TrimPrefix(target, "/")
495		if sourceTopicSlug != "" {
496			prefix := strings.Trim(sourceTopicSlug, "/") + "/"
497			target = strings.TrimPrefix(target, prefix)
498		}
499		return conceptKey(target) + ".md" + fragment
500	}
501	
502	func stripFragment(target string) string {
503		if before, _, found := strings.Cut(target, "#"); found {
504			return before
505		}
506		return target
507	}
508	
509	func fallbackWikiLabel(target string) string {
510		target = stripFragment(target)
511		return vault.HumanizeSlug(conceptKey(target))
512	}
513	
514	func dedupeStrings(values []string) []string {
515		if len(values) == 0 {
516			return nil
517		}
518		deduped := values[:0]
519		var previous string
520		for index, value := range values {
521			if index > 0 && value == previous {
522				continue
523			}
524			deduped = append(deduped, value)
525			previous = value
526		}
527		return append([]string(nil), deduped...)
528	}
