530	func loadConcepts(bundlePath string) ([]conceptInfo, string, error) {
531		okfVersion := OKFVersion
532		indexPath := filepath.Join(bundlePath, "index.md")
533		if content, err := os.ReadFile(indexPath); err == nil {
534			values, _, parseErr := frontmatter.Parse(string(content))
535			if parseErr != nil {
536				return nil, "", fmt.Errorf("parse index.md: %w", parseErr)
537			}
538			if version := strings.TrimSpace(frontmatter.GetString(values, "okf_version")); version != "" {
539				okfVersion = version
540			}
541		} else if !errors.Is(err, os.ErrNotExist) {
542			return nil, "", fmt.Errorf("read index.md: %w", err)
543		}
544	
545		concepts := make([]conceptInfo, 0)
546		err := filepath.WalkDir(bundlePath, func(currentPath string, entry fs.DirEntry, walkErr error) error {
547			if walkErr != nil {
548				return walkErr
549			}
550			if currentPath == bundlePath {
551				return nil
552			}
553			if entry.Type()&fs.ModeSymlink != 0 {
554				return nil
555			}
556			if entry.IsDir() {
557				if strings.HasPrefix(entry.Name(), ".") {
558					return filepath.SkipDir
559				}
560				return nil
561			}
562			if !strings.EqualFold(filepath.Ext(entry.Name()), ".md") || isExcludedMarkdown(entry.Name()) {
563				return nil
564			}
565			relativePath, err := filepath.Rel(bundlePath, currentPath)
566			if err != nil {
567				return err
568			}
569			relativePath = vault.ToPosixPath(relativePath)
570			if isIndexFile(relativePath) || isLogFile(relativePath) {
571				return nil
572			}
573			content, err := os.ReadFile(currentPath)
574			if err != nil {
575				return err
576			}
577			values, _, err := frontmatter.Parse(string(content))
578			if err != nil || len(values) == 0 {
579				return nil
580			}
581			conceptType := strings.TrimSpace(frontmatter.GetString(values, "type"))
582			title := strings.TrimSpace(frontmatter.GetString(values, "title"))
583			if title == "" {
584				title = vault.HumanizeSlug(conceptKey(relativePath))
585			}
586			concepts = append(concepts, conceptInfo{
587				RelativePath: relativePath,
588				Type:         firstNonEmpty(conceptType, "Concept"),
589				Title:        title,
590				Description:  strings.TrimSpace(frontmatter.GetString(values, "description")),
591			})
592			return nil
593		})
594		if err != nil {
595			return nil, "", fmt.Errorf("scan concepts: %w", err)
596		}
597		return concepts, okfVersion, nil
598	}
