600	func checkConceptFile(filePath, relativePath string, typeSet map[string]struct{}, strict bool) []models.LintIssue {
601		content, err := os.ReadFile(filePath)
602		if err != nil {
603			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("read concept: %v", err))}
604		}
605		values, _, err := frontmatter.Parse(string(content))
606		if err != nil {
607			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("frontmatter is invalid: %v", err))}
608		}
609		if len(values) == 0 {
610			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "type", "concept must start with YAML frontmatter")}
611		}
612		issues := make([]models.LintIssue, 0)
613		conceptType := strings.TrimSpace(frontmatter.GetString(values, "type"))
614		if conceptType == "" {
615			issues = append(issues, newIssue(models.SeverityError, relativePath, "type", "concept frontmatter must include non-empty type"))
616		}
617		for _, field := range []string{"title", "description", "timestamp"} {
618			if strings.TrimSpace(frontmatter.GetString(values, field)) == "" {
619				issues = append(issues, newIssue(warningSeverity(strict), relativePath, field, fmt.Sprintf("producer field %q is missing", field)))
620			}
621		}
622		if len(typeSet) > 0 && conceptType != "" {
623			if _, ok := typeSet[conceptType]; !ok {
624				issues = append(issues, newIssue(warningSeverity(strict), relativePath, "type", fmt.Sprintf("type %q is outside the configured OKF vocabulary", conceptType)))
625			}
626		}
627		return issues
628	}
