655	func checkLogFile(filePath, relativePath string, strict bool) []models.LintIssue {
656		content, err := os.ReadFile(filePath)
657		if err != nil {
658			return []models.LintIssue{newIssue(models.SeverityError, relativePath, "", fmt.Sprintf("read log: %v", err))}
659		}
660		issues := make([]models.LintIssue, 0)
661		for line := range strings.SplitSeq(string(content), "\n") {
662			trimmed := strings.TrimSpace(line)
663			if !strings.HasPrefix(trimmed, "## ") {
664				continue
665			}
666			dateValue := strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
667			if _, err := time.Parse(frontmatter.DateLayout, dateValue); err != nil {
668				issues = append(issues, newIssue(models.SeverityError, relativePath, "date", fmt.Sprintf("log heading %q must use YYYY-MM-DD", trimmed)))
669			}
670		}
671		_ = strict
672		return issues
673	}
