692	func sortIssues(issues []models.LintIssue) {
693		sort.Slice(issues, func(i, j int) bool {
694			if issues[i].Severity != issues[j].Severity {
695				return issues[i].Severity < issues[j].Severity
696			}
697			if issues[i].FilePath != issues[j].FilePath {
698				return issues[i].FilePath < issues[j].FilePath
699			}
700			if issues[i].Target != issues[j].Target {
701				return issues[i].Target < issues[j].Target
702			}
703			return issues[i].Message < issues[j].Message
704		})
705	}
