715	func isExcludedMarkdown(name string) bool {
716		lower := strings.ToLower(strings.TrimSpace(name))
717		switch lower {
718		case "claude.md", "agents.md", "readme.md", "license.md", "notice.md", "attribution.md":
719			return true
720		default:
721			return strings.HasPrefix(lower, "license.") || strings.HasPrefix(lower, "notice.") || strings.HasPrefix(lower, "attribution.")
722		}
723	}
