725	func insertLogEntry(content, dateHeading, entry string) string {
726		lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
727		if len(lines) == 0 || strings.TrimSpace(lines[0]) == "" {
728			lines = []string{"# Directory Update Log"}
729		}
730		heading := "## " + dateHeading
731		for index, line := range lines {
732			if strings.TrimSpace(line) != heading {
733				continue
734			}
735			next := append([]string{}, lines[:index+1]...)
736			next = append(next, entry)
737			next = append(next, lines[index+1:]...)
738			return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
739		}
740		next := []string{strings.TrimRight(strings.Join(lines[:1], "\n"), "\n"), "", heading, "", entry}
741		if len(lines) > 1 {
742			rest := strings.TrimSpace(strings.Join(lines[1:], "\n"))
743			if rest != "" {
744				next = append(next, "", rest)
745			}
746		}
747		return strings.TrimRight(strings.Join(next, "\n"), "\n") + "\n"
748	}
749	
750	func firstNonEmpty(values ...string) string {
751		for _, value := range values {
752			if trimmed := strings.TrimSpace(value); trimmed != "" {
753				return trimmed
754			}
755		}
756		return ""
757	}
