313	func parseFrontmatter(t *testing.T, body string) (map[string]any, string) {
314		t.Helper()
315	
316		if !strings.HasPrefix(body, "---\n") {
317			t.Fatalf("body missing leading frontmatter delimiter:\n%s", body)
318		}
319	
320		remainder := strings.TrimPrefix(body, "---\n")
321		before, after, ok := strings.Cut(remainder, "\n---\n")
322		if !ok {
323			t.Fatalf("body missing closing frontmatter delimiter:\n%s", body)
324		}
325	
326		var parsed map[string]any
327		frontmatterBlock := before
328		if err := yaml.Unmarshal([]byte(frontmatterBlock), &parsed); err != nil {
329			t.Fatalf("frontmatter did not parse as YAML: %v\n%s", err, frontmatterBlock)
330		}
331	
332		return parsed, after
333	}
